/** Recommended voices per language, with the score those voices earned reading it. */
export const RECOMMENDED = LANGUAGES.map((lang) => {
    const scored = [...lang.female, ...lang.male]
        .map((name) => VOICES[name]?.judgeNative)
        .filter((score) => typeof score === 'number');

    return {
        ...lang,
        judge: scored.length ? scored.reduce((a, b) => a + b, 0) / scored.length : null,
    };
});

/** Language code to display name, for the many places a clip carries only the code. */
export const LANG_NAME = Object.fromEntries(LANGUAGES.map((lang) => [lang.code, lang.name]));

/** The ten benchmarked codes, in the order the language tabs and the chart use. */
export const BENCHMARKED = LANGUAGES.filter((lang) => lang.benchmarked).map((lang) => lang.code);
